"use client";
import { useEffect,useState,useRef,type ReactNode } from "react";
import { Aperture,ArrowRight,ArrowUpRight,AudioLines,BookOpen,Check,CheckCheck,ChevronDown,ChevronLeft,ChevronRight,CircleAlert,Clapperboard,Clock3,Copy,Download,ExternalLink,FileText,Film,FolderOpen,Image as ImageIcon,Layers3,Link2,Loader2,LockKeyhole,Mic,MoreHorizontal,Music2,Palette,Play,Plus,RefreshCw,Scissors,Settings2,ShieldCheck,Sparkles,Trash2,Upload,Users,Video,Volume2,X,ArrowUp,ArrowDown,History } from "lucide-react";
import { type State,type Project,type Scene,type Element,type FileRef,type Line,checks,preflight,promptFor,elementName,seconds,defaultRules,visualLabels,type VisualDetails } from "../lib/core";
import { upload,extractFrames,mediaUrl,download,flowPack,productionPack,renderInBrowser } from "../lib/browser-media";
import { readJsonResponse } from "../lib/http";
import { referenceProposal,type ReferenceReading,type TokenUsage,type CostEstimate } from "../lib/reference";

type View="studio"|"script"|"library"|"assembly"|"settings"|"history";
const labels:Record<string,string>={draft:"A preparar",review:"Em revisão",approved:"Aprovada",stale:"Regravar",generating:"Gerando"};
function Badge({status}:{status:string}){return <span className={`badge ${status}`}><span className="dot"/>{labels[status]||status}</span>;}
function Button({children,onClick,kind="secondary",disabled=false,className="",type="button"}:{children:ReactNode;onClick?:()=>void;kind?:string;disabled?:boolean;className?:string;type?:"button"|"submit"}){return <button type={type} className={`btn ${kind} ${className}`} onClick={onClick} disabled={disabled}>{children}</button>;}
function Field({label,children,hint}:{label:string;children:ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
function Empty({icon=<Film size={28}/>,title,text,children}:{icon?:ReactNode;title:string;text:string;children?:ReactNode}){return <div className="empty"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p>{children}</div>;}
const fileName=(s:string)=>s.replace(/[^a-zA-Z0-9À-ÿ._-]+/g,"-");
type AnalysisResponse={proposal?:Partial<Element>;error?:string;reused?:boolean;inputTokens?:number};

export default function Studio(){
  const [state,setState]=useState<State|null>(null),[view,setView]=useState<View>("studio"),[selected,setSelected]=useState(""),[busy,setBusy]=useState(""),[error,setError]=useState(""),[notice,setNotice]=useState(""),[key,setKey]=useState(""),[configured,setConfigured]=useState(false),[editor,setEditor]=useState<Element|null>(null),[newName,setNewName]=useState<string|null>(null),[filter,setFilter]=useState<"character"|"environment">("character"),[tab,setTab]=useState("production"),[autoQueue,setAutoQueue]=useState(false);
  const [rendering,setRendering]=useState(false),[progress,setProgress]=useState(0),[result,setResult]=useState<{url:string;extension:string}|null>(null);const controller=useRef<AbortController|null>(null);
  const busyRef=useRef(false);
  async function load(){try{setError("");const r=await fetch("/api/studio",{cache:"no-store"});const d:any=await readJsonResponse(r);if(!r.ok)throw new Error(d.error);setState(d.state);setConfigured(d.configured);}catch(e){setError(e instanceof Error?e.message:"Falha ao abrir o estúdio.");}}
  useEffect(()=>{load();},[]);
  useEffect(()=>{if(notice){const t=setTimeout(()=>setNotice(""),5000);return()=>clearTimeout(t);}},[notice]);
  useEffect(()=>{return()=>{if(result)URL.revokeObjectURL(result.url);};},[result]);
  const p=state?.projects.find(x=>x.id===state.selectedProject)||state?.projects[0];const scene=p?.scenes.find(s=>s.id===selected)||p?.scenes[0];
  async function run(label:string,fn:()=>Promise<void>){if(busyRef.current)return;busyRef.current=true;setBusy(label);setError("");try{await fn();}catch(e){setError(e instanceof Error?e.message:"Não foi possível concluir.");}finally{busyRef.current=false;setBusy("");}}
  async function raw(type:string,payload:any={},sid?:string){
    const res=await fetch("/api/studio",{method:"POST",headers:{"Content-Type":"application/json",...(key?{"x-google-key":key}:{})},body:JSON.stringify({type,payload,revision:state!.revision,projectId:p?.id,sceneId:sid||scene?.id})});
    let data:any;try{data=await readJsonResponse(res);}catch(e){if(["analyzeElement","generate","poll"].includes(type))await load();throw e;}
    if(data.state)setState(data.state);
    if(!res.ok||data.error){if(res.status===409)await load();throw new Error(data.error||"Não foi possível salvar.");}return data;
  }
  async function analyzeReference(draft:Element,force=false,countOnly=false):Promise<AnalysisResponse>{
    let response:AnalysisResponse={};
    await run(countOnly?"Contando tokens de entrada":"Analisando a imagem e preenchendo a ficha",async()=>{
      try{const d=await raw(countOnly?"countElementTokens":"analyzeElement",{id:draft.id||undefined,kind:draft.kind,name:draft.name,rules:draft.rules,palette:draft.palette,voice:draft.voice,files:draft.files,force});response={proposal:d.proposal,reused:d.reused,inputTokens:d.inputTokens};}
      catch(e){response={error:e instanceof Error?e.message:"A leitura da imagem não foi concluída."};throw e;}
    });return response;
  }
  async function act(type:string,payload:any={},sid?:string){await run("Salvando",async()=>{await raw(type,payload,sid);setNotice("Alterações salvas.");});}
  async function importVideo(file:File){if(!scene)return;await run("Importando vídeo e extraindo frames",async()=>{const object=URL.createObjectURL(file);try{const frames=await extractFrames(object);const video=await upload(file);const firstFrame=await upload(frames.first,`${scene.id}-primeiro.png`),lastFrame=await upload(frames.last,`${scene.id}-ultimo.png`);await raw("attachVideo",{video,firstFrame,lastFrame,duration:frames.duration,width:frames.width,height:frames.height});setTab("review");setNotice("Vídeo importado. Revise o clipe completo antes de aprovar.");}finally{URL.revokeObjectURL(object);}});}
  async function framesFromSaved(){if(!scene?.video)return;await run("Extraindo frames do vídeo",async()=>{const f=await extractFrames(mediaUrl(scene.video!));await raw("extractFrames",{firstFrame:await upload(f.first,`${scene.id}-primeiro.png`),lastFrame:await upload(f.last,`${scene.id}-ultimo.png`),duration:f.duration,width:f.width,height:f.height});setTab("review");});}
  async function uploadAudio(file:File,kind:string){await run("Enviando áudio",async()=>{await raw("setAudio",{kind,file:await upload(file)});setNotice("Áudio salvo.");});}
  useEffect(()=>{
    if(!autoQueue||!state||!p||busy||rendering)return;
    const next=p.scenes.find(s=>s.status!=="approved");
    if(!next){setAutoQueue(false);setNotice("Todas as cenas estão aprovadas. A montagem está liberada.");return;}
    setSelected(next.id);
    if(next.status==="review"){
      setTab("review");
      if(next.video&&!next.lastFrame){const timer=setTimeout(()=>{run("Extraindo frames da cena gerada",async()=>{const f=await extractFrames(mediaUrl(next.video!));await raw("extractFrames",{firstFrame:await upload(f.first,`${next.id}-primeiro.png`),lastFrame:await upload(f.last,`${next.id}-ultimo.png`),duration:f.duration,width:f.width,height:f.height},next.id);}).catch(()=>{});},500);return()=>clearTimeout(timer);}
      return;
    }
    if(next.status==="stale"){setAutoQueue(false);setError("A sequência pausou: há uma tomada com contexto alterado. Gere ou importe uma nova versão.");return;}
    if(next.generationError&&!next.operation){setAutoQueue(false);setError(next.generationError);return;}
    if(!key&&!configured){setAutoQueue(false);setError("Configure a conexão de geração em Integrações para a produção sequencial.");return;}
    const issues=preflight(p,next,state.elements);
    if(issues.length){setAutoQueue(false);setError(issues.join(" "));return;}
    const timer=setTimeout(()=>{run(next.operation?"Consultando geração sequencial":"Gerando próxima cena",async()=>{try{const d=await raw(next.operation?"poll":"generate",{},next.id);if(d.needsAttention)setAutoQueue(false);}catch(e){setAutoQueue(false);await load();throw e;}});},next.operation?12000:800);
    return()=>clearTimeout(timer);
  },[autoQueue,state,busy,key,configured,rendering]);
  async function openElement(kind:Element["kind"]){setEditor({id:"",kind,name:"",rules:kind==="character"?defaultRules:"Descreva a arquitetura, objetos, materiais, escala e iluminação que devem ser preservados.",palette:"",voice:"",voiceId:"",files:[],approved:false,version:0});}
  if(!state||!p)return <div className="loading-page"><div className="brand-symbol"><Aperture/></div><h2>Contínuo</h2>{error?<><p className="error-text">{error}</p><Button onClick={load}>Tentar novamente</Button></>:<><Loader2 className="spin"/><p>Abrindo seu estúdio…</p></>}</div>;
  const directReady=!!key||configured;
  const approved=p.scenes.filter(s=>s.status==="approved").length,total=p.scenes.reduce((n,s)=>n+s.duration,0),ready=state.elements.filter(e=>e.approved).length;
  const nav=[{id:"studio",label:"Estúdio",icon:Clapperboard},{id:"script",label:"Roteiro",icon:FileText},{id:"library",label:"Biblioteca oficial",icon:Layers3},{id:"assembly",label:"Áudio e montagem",icon:AudioLines}] as const;
  return <div className="app-shell">
    <aside className="sidebar"><a className="brand" href="#" onClick={e=>{e.preventDefault();setView("studio");}}><div className="brand-symbol"><Aperture size={25}/></div><div><strong>contínuo<span>®</span></strong><small>GOODEA STUDIO</small></div></a>
      <div className="workspace-label">SEU ESPAÇO DE CRIAÇÃO</div><nav>{nav.map(n=><button key={n.id} className={view===n.id?"nav-item active":"nav-item"} onClick={()=>setView(n.id)}><n.icon size={19}/><span>{n.label}</span>{n.id==="library"&&<em>{state.elements.length}</em>}</button>)}</nav>
      <div className="sidebar-divider"/><div className="workspace-label project-label">PROJETOS <button aria-label="Criar projeto" onClick={()=>setNewName("")}><Plus size={16}/></button></div><div className="project-nav">{state.projects.map(project=><button key={project.id} className={project.id===p.id?"project-item selected":"project-item"} onClick={()=>run("Abrindo projeto",async()=>{const res=await fetch("/api/studio",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:"selectProject",projectId:project.id,revision:state.revision})});const d:any=await readJsonResponse(res);if(!res.ok)throw new Error(d.error);setState(d.state);setSelected("");setView("studio");})}><span className="project-dot"/>{project.name.split(" · ")[0]}</button>)}</div>
      <div className="sidebar-bottom"><div className="continuity-card"><ShieldCheck size={20}/><strong>Identidade em primeiro lugar.</strong><p>Referências oficiais e revisão em cada cena.</p><div className="mini-progress"><span style={{width:`${state.elements.length?ready/state.elements.length*100:0}%`}}/></div><small>{ready} de {state.elements.length} fichas aprovadas</small></div><button className={view==="settings"?"nav-item active":"nav-item"} onClick={()=>setView("settings")}><Settings2 size={18}/>Integrações</button><button className={view==="history"?"nav-item active":"nav-item"} onClick={()=>setView("history")}><History size={18}/>Histórico</button><div className="account"><div className="avatar">G</div><div><strong>Goodea</strong><span>Estúdio local</span></div><LockKeyhole size={14}/></div></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb">Meu estúdio <ChevronRight size={14}/><span>{view==="studio"?"Produção":view==="script"?"Roteiro":view==="library"?"Biblioteca":view==="assembly"?"Montagem":view==="settings"?"Integrações":"Histórico"}</span></div><div className="top-actions"><span className="saved"><span className="dot"/>{busy||"Salvo no estúdio"}</span><button className="icon-button" title="Recarregar dados" aria-label="Recarregar dados" onClick={load} disabled={!!busy}><RefreshCw size={17}/></button><div className="top-avatar">G</div></div></header>
      <main className="content">
        {error&&<div className="alert error" role="alert"><CircleAlert size={18}/><span>{error}</span><button onClick={()=>setError("")} aria-label="Fechar aviso"><X size={16}/></button></div>}
        {view==="studio"&&<><div className="page-heading"><div><div className="eyebrow"><span/>ESTÚDIO DE PRODUÇÃO</div><h1>Cena a cena.<br/><span>Uma só história.</span></h1><p>Do roteiro ao último frame, mantenha seu universo conectado.</p></div><Button kind="primary" onClick={()=>setView("script")}><FileText size={16}/>Editar roteiro<ArrowUpRight size={16}/></Button></div>
          <div className="project-strip"><div className="project-title"><div className="project-icon"><Clapperboard size={23}/></div><div><small>PROJETO ATUAL</small><h2>{p.name}</h2></div></div><div className="project-metrics"><div><Film size={16}/><strong>{p.scenes.length}</strong><span>cenas</span></div><div><Clock3 size={16}/><strong>{seconds(total)}</strong><span>previstos</span></div><span className="format-tag">{p.aspect}</span></div></div>
          <VideoProfileControls p={p} busy={!!busy} onAspect={aspect=>act("saveProject",{...p,aspect})}/>
          <div className="workflow"><div className="workflow-step done"><span>01</span><div><strong>Roteiro</strong><small>História e direção</small></div><Check size={15}/></div><div className={`workflow-step ${ready?"done":"current"}`}><span>02</span><div><strong>Referências</strong><small>{ready}/{state.elements.length} fichas oficiais</small></div></div><div className="workflow-step current"><span>03</span><div><strong>Produção e revisão</strong><small>{approved}/{p.scenes.length} cenas aprovadas</small></div></div><div className="workflow-step"><span>04</span><div><strong>Montagem</strong><small>O filme completo</small></div></div></div>
          <div className="queue-banner"><div><Sparkles size={18}/><div><strong>Produção sequencial com Omni Flash</strong><p>{autoQueue?"Ligada · consulta as gerações e pausa em cada revisão. A aba precisa permanecer aberta.":"Gere uma cena de cada vez, com revisão obrigatória antes da próxima."}</p></div></div><Button kind={autoQueue?"secondary":"primary"} disabled={!!busy||!p.scenes.length} onClick={()=>{if(autoQueue){setAutoQueue(false);setNotice("Sequência pausada. Uma geração já enviada ao Google continua no provedor.");}else if(!directReady){setView("settings");setNotice("Configure a conexão de geração para ativar a sequência.");}else setAutoQueue(true);}}>{autoQueue?<><Clock3 size={14}/>Pausar sequência</>:<><Play size={14}/>Ativar sequência</>}</Button></div><div className="section-heading"><div><h2>Sequência de cenas <span className="count">{p.scenes.length}</span></h2><p>A cena seguinte começa onde a anterior termina.</p></div><Button kind="ghost" onClick={()=>act("addScene")} disabled={!!busy}><Plus size={16}/>Adicionar cena</Button></div>
          <div className="production-layout"><div className="scenes-column">{p.scenes.length?<div className="scene-list">{p.scenes.map((s,i)=><button key={s.id} onClick={()=>{setSelected(s.id);setTab("production");}} className={`scene-card ${scene?.id===s.id?"selected":""}`}><div className="scene-number">{String(i+1).padStart(2,"0")}</div><div className="scene-thumb">{s.firstFrame?<img src={mediaUrl(s.firstFrame)} alt="Primeiro frame da cena"/>:<div className="thumb-placeholder"><Clapperboard size={22}/></div>}<span>{s.duration}s</span></div><div className="scene-copy"><strong>{s.title}</strong><small>{elementName(s.environment,state.elements)}</small><div className="cast-mini">{s.characters.slice(0,3).map(id=><span key={id}>{elementName(id,state.elements).split(" ")[0]}</span>)}</div></div><Badge status={s.status}/><ChevronRight size={16}/></button>)}</div>:<Empty title="Sua história começa no roteiro" text="Escreva ou cole o roteiro para identificar as cenas, o elenco e os ambientes."><Button onClick={()=>setView("script")}>Abrir roteiro<ArrowRight size={16}/></Button></Empty>}
            <div className="sequence-tip"><Link2 size={18}/><div><strong>O último frame é o próximo começo.</strong><p>Apenas o frame de uma cena aprovada libera a continuidade. Alterou uma tomada? As seguintes voltam para revisão.</p></div></div>
            <div className="progress-card"><div><ShieldCheck size={17}/><strong>Progresso do episódio</strong><span>{Math.round(approved/Math.max(1,p.scenes.length)*100)}%</span></div><div className="mini-progress"><span style={{width:`${approved/Math.max(1,p.scenes.length)*100}%`}}/></div><small>{approved} de {p.scenes.length} cenas aprovadas para montagem</small></div>
          </div>
          {scene&&<section className="scene-panel"><div className="panel-heading"><div><span className="eyebrow">CENA {String(p.scenes.indexOf(scene)+1).padStart(2,"0")}</span><h2>{scene.title}</h2></div><Badge status={scene.status}/></div><div className="panel-tabs">{[["production","Produção"],["direction","Direção"],["review","Revisão"]].map(([id,label])=><button className={tab===id?"active":""} key={id} onClick={()=>setTab(id)}>{label}</button>)}</div>
            {tab==="production"&&<div className="panel-body"><div className={`video-stage ${p.aspect==="9:16"?"portrait":""}`}>{scene.video?<video key={scene.video.id} src={mediaUrl(scene.video)} controls playsInline preload="metadata"/>:<div className="stage-empty"><div className="film-orbit"><Aperture size={34}/></div><span>SEU UNIVERSO EM MOVIMENTO</span><h3>Uma cena para chamar de sua.</h3><p>Prepare as referências e importe o vídeo gerado.</p></div>}</div>
              {scene.generationError&&<div className="alert error"><CircleAlert size={16}/>{scene.generationError}</div>}
              <div className="scene-details"><span><Users size={14}/>{scene.characters.length} personagens</span><span><Clock3 size={14}/>{scene.actualDuration?scene.actualDuration.toFixed(2):scene.duration}s</span><span><Link2 size={14}/>{scene.transition==="continue"?"Continuidade":"Corte planejado"}</span></div><p className="scene-action">{scene.action||"Descreva a ação na aba Direção."}</p>
              <div className="readiness"><div><ShieldCheck size={17}/><strong>Antes de gerar</strong><span>{preflight(p,scene,state.elements).length?`${preflight(p,scene,state.elements).length} pendências`:"Tudo preparado"}</span></div>{preflight(p,scene,state.elements).length?<ul>{preflight(p,scene,state.elements).map((e,i)=><li key={i}>{e}</li>)}</ul>:<p className="success-text"><Check size={15}/>Referências e cena anterior aprovadas.</p>}</div>
              <div className="flow-actions"><Button kind="primary" disabled={!!busy||!!preflight(p,scene,state.elements).length} onClick={()=>run("Preparando pacote Flow",async()=>{download(await flowPack(p,scene,state.elements),`Flow-Cena-${p.scenes.indexOf(scene)+1}.zip`);setNotice("Pacote baixado com prompt, referências e frame anterior.");})}><Download size={16}/>Pacote para o Flow</Button><label className={`btn secondary file-btn ${busy||preflight(p,scene,state.elements).length?"disabled":""}`}><Upload size={16}/>Importar vídeo<input type="file" accept="video/mp4,video/webm,video/quicktime" disabled={!!busy||!!preflight(p,scene,state.elements).length} onChange={e=>{const f=e.target.files?.[0];if(f)importVideo(f);e.target.value="";}}/></label></div>
              <div className="flow-help"><a href={p.flowProjectUrl||"https://flow.google.com/"} target="_blank" rel="noreferrer">{`Abrir ${p.flowProjectUrl?"projeto no Flow":"Google Flow"}`}<ExternalLink size={12}/></a><span>Gere no Flow e importe o clipe aqui.</span></div>
              <DirectGeneration p={p} scene={scene} elements={state.elements} ready={directReady} busy={!!busy} onSettings={()=>setView("settings")} onGenerate={()=>run("Enviando cena à API Omni Flash",async()=>{await raw("generate");setNotice("Geração enviada. Consulte o andamento; não é necessário reenviar.");})} onPoll={()=>run("Consultando geração",async()=>{const d=await raw("poll");setNotice(d.pending?"A geração continua em andamento.":"Consulta concluída.");})}/>
              {scene.video&&!scene.lastFrame&&<Button onClick={framesFromSaved} disabled={!!busy}><Scissors size={16}/>Extrair frames do vídeo</Button>}
              {(scene.firstFrame||scene.lastFrame)&&<div className="frame-pair">{[[scene.firstFrame,"Frame inicial"],[scene.lastFrame,"Último frame · continuidade"]].map(([f,label],i)=><div key={i}>{f&&<a href={mediaUrl(f as FileRef)} target="_blank" rel="noreferrer"><img src={mediaUrl(f as FileRef)} alt={label as string}/></a>}<span>{label as string}</span></div>)}</div>}
              {scene.attempts.length>0&&<details><summary>{scene.attempts.length} tomadas anteriores preservadas</summary>{scene.attempts.map((a,i)=><a className="file-row" key={a.video.id+i} href={mediaUrl(a.video)} target="_blank" rel="noreferrer"><Video size={15}/>Tomada {i+1}<ExternalLink size={13}/></a>)}</details>}
            </div>}
            {tab==="direction"&&<SceneEditor key={`${scene.id}-${state.revision}`} scene={scene} elements={state.elements} busy={!!busy} onSave={data=>act("saveScene",data)} onMove={direction=>act("moveScene",{direction})} onRemove={()=>{if(window.confirm("Remover esta cena? A continuidade das seguintes precisará ser refeita."))act("removeScene");}} onPrompt={()=>{navigator.clipboard.writeText(promptFor(p,scene,state.elements)).then(()=>setNotice("Prompt copiado."),()=>setError("Não foi possível copiar. Use o arquivo prompt.txt do pacote Flow."));}}/>}
            {tab==="review"&&<Review key={`${scene.id}-${state.revision}`} scene={scene} busy={!!busy} pending={preflight(p,scene,state.elements)} onSave={data=>act("review",data)} onReject={notes=>act("reject",{notes})} onAudit={()=>run("Analisando o clipe completo com IA",async()=>{await raw("audit");setNotice("Auditoria concluída. Confira os achados.");})} onFrames={framesFromSaved}/>}
          </section>}
          </div></>}
        {view==="script"&&<><PageTitle eyebrow="A HISTÓRIA PRIMEIRO" title="Roteiro e direção." text="Separe ação, fala e narração. A continuidade começa antes de gerar."/><ScriptEditor key={`${p.id}-${state.revision}`} p={p} busy={!!busy} onParse={(script,ai)=>run(ai?"Identificando roteiro com IA":"Identificando cenas",async()=>{await raw(ai?"parseAI":"parseScript",{script});setSelected("");setView("studio");setNotice("Cenas identificadas. Revise as informações antes de produzir.");})} onSave={data=>act("saveProject",data)}/></>}
        {view==="library"&&<><div className="title-actions"><PageTitle eyebrow="A FONTE DA VERDADE" title="Seu universo, preservado." text="Uma ficha oficial para cada personagem e cada lugar da sua história."/><Button kind="primary" onClick={()=>openElement(filter)}><Plus size={16}/>Novo {filter==="character"?"personagem":"ambiente"}</Button></div><div className="library-toolbar"><div className="segmented"><button className={filter==="character"?"active":""} onClick={()=>setFilter("character")}><Users size={16}/>Personagens</button><button className={filter==="environment"?"active":""} onClick={()=>setFilter("environment")}><ImageIcon size={16}/>Ambientes</button></div><span>{state.elements.filter(e=>e.kind===filter).length} cadastros</span></div><div className="library-notice"><LockKeyhole size={17}/><p>Os nomes iniciais são cadastros em preparação. Importe as fichas e imagens oficiais para aprovar a identidade. Nenhuma aparência foi inventada.</p></div><div className="library-grid">{state.elements.filter(e=>e.kind===filter).map(e=><button key={e.id} className="element-card" onClick={()=>setEditor(structuredClone(e))}><div className="element-image">{e.files.find(f=>f.mime.startsWith("image/"))?<img src={mediaUrl(e.files.find(f=>f.mime.startsWith("image/"))!)} alt={`Referência ${e.name}`}/>:<div className="element-placeholder">{e.kind==="character"?<Users size={34}/>:<ImageIcon size={34}/>}<span>Referência oficial</span><small>Aguardando imagem</small></div>}<span className="version">v{e.version}</span><span className={`canonical-tag ${e.approved?"approved":""}`}>{e.approved?<><ShieldCheck size={12}/>Oficial</>:<><Clock3 size={12}/>Em preparação</>}</span></div><div className="element-info"><h3>{e.name}<ArrowUpRight size={17}/></h3><p>{e.files.length} arquivos de referência{e.kind==="character"?` · ${e.voiceId?"voz definida":"voz pendente"}`:""}</p></div></button>)}<button className="add-element" onClick={()=>openElement(filter)}><div><Plus size={24}/></div><strong>Expandir o universo</strong><span>Cadastrar {filter==="character"?"personagem":"ambiente"}</span></button></div></>}
        {view==="assembly"&&<><PageTitle eyebrow="TODAS AS PARTES, UM FILME" title="O encontro das cenas." text="Uma trilha contínua, as mesmas vozes e uma montagem na ordem certa."/><div className="assembly-grid"><section className="surface"><div className="surface-title"><AudioLines size={20}/><h2>Identidade sonora</h2></div><AudioUpload title="Trilha musical contínua" text="A mesma faixa percorre o filme. Repete até o final." file={p.music} busy={!!busy} onFile={f=>uploadAudio(f,"music")} onRemove={()=>act("setAudio",{kind:"music",file:null})}/><AudioUpload title="Faixa mestre de vozes e narração" text="Use um áudio completo com as vozes oficiais e os tempos do roteiro." file={p.narration} busy={!!busy} onFile={f=>uploadAudio(f,"narration")} onRemove={()=>act("setAudio",{kind:"narration",file:null})}/><MixSettings key={state.revision} p={p} busy={!!busy} onSave={data=>act("saveProject",data)}/><div className="info-note"><Mic size={17}/><p>Uma descrição de voz no prompt não fixa a voz do Flow. Para maior consistência, use as mesmas gravações oficiais na faixa mestre ou substitua o áudio de cada cena. A sincronização precisa de revisão.</p></div></section><section className="surface"><div className="surface-title"><Scissors size={20}/><h2>Montagem final</h2><span className="tiny-tag">{p.aspect}</span></div><div className="assembly-counter"><strong>{approved}<span>/{p.scenes.length}</span></strong><div>cenas aprovadas<small>{seconds(total)} de história planejada</small></div></div><div className="montage-list">{p.scenes.map((s,i)=><div key={s.id}><span>{String(i+1).padStart(2,"0")}</span><strong>{s.title}</strong><Badge status={s.status}/></div>)}</div>{approved!==p.scenes.length||!p.scenes.length?<div className="locked-note"><LockKeyhole size={16}/>A montagem fica disponível após a aprovação de todas as cenas.</div>:<div className="success-text"><CheckCheck size={17}/>Todas as cenas liberadas para montagem.</div>}
          <Button kind="primary" disabled={!!busy||rendering||approved!==p.scenes.length||!p.scenes.length} onClick={()=>run("Preparando o pacote de montagem",async()=>{download(await productionPack(p,state.elements,setBusy),`${fileName(p.name)}-MP4.zip`);setNotice("Pacote baixado. Execute render_mp4.py na pasta extraída para montar o filme.");})}><Download size={16}/>Exportar pacote MP4</Button><p className="help-text">Inclui clipes, áudios, roteiro e o montador. No computador com Python e FFmpeg, um comando cria o filme MP4.</p><Button disabled={!!busy||rendering||approved!==p.scenes.length||!p.scenes.length} onClick={async()=>{setError("");setRendering(true);setBusy("Montando prévia em tempo real");setProgress(0);controller.current=new AbortController();try{const output=await renderInBrowser(p,setProgress,controller.current.signal);setResult({url:URL.createObjectURL(output.blob),extension:output.extension});}catch(e){setError(e instanceof Error?e.message:"Falha na montagem.");}finally{setRendering(false);setBusy("");}}}><Play size={16}/>Montar prévia no navegador</Button><p className="help-text">Até 10 minutos. Exportação em tempo real, normalmente WebM. Mantenha esta aba aberta e visível.</p>{rendering&&<div className="render-progress"><progress value={progress} max={100}/><span>{Math.round(progress)}% · Montando em tempo real</span><Button onClick={()=>controller.current?.abort()}>Cancelar montagem</Button></div>}{result&&<div className="render-result"><video controls src={result.url}/><a className="btn primary" href={result.url} download={`${fileName(p.name)}.${result.extension}`}><Download size={16}/>Baixar vídeo completo</a></div>}</section></div>{scene&&<section className="surface scene-audio"><div className="surface-title"><Volume2 size={20}/><h2>Áudio por cena</h2></div><p className="muted">Substitui o áudio original somente na cena escolhida. Selecione outra cena no Estúdio para alterar.</p><h3>{scene.title}</h3><AudioUpload title="Vozes oficiais desta cena" text="O arquivo deve ter o mesmo tempo do clipe. Mantenha os silêncios e as entradas de fala." file={scene.audio} busy={!!busy} onFile={f=>uploadAudio(f,"scene")} onRemove={()=>act("setAudio",{kind:"scene",file:null})}/></section>}</>}
        {view==="settings"&&<><PageTitle eyebrow="CONEXÕES DE PRODUÇÃO" title="Seu estúdio, conectado." text="Prepare as cenas para usar no Flow e configure a Gemini API para a análise das fichas."/><div className="integration-grid"><section className="surface"><div className="integration-icon flow-icon"><Aperture size={28}/></div><div className="integration-heading"><h2>Produção assistida no Flow</h2><span className="badge review">Manual</span></div><p>Use sua conta do Flow para gerar os clipes. O Contínuo prepara o prompt, as referências oficiais e o último frame aprovado; você importa o resultado para revisar.</p><FlowSetupGuide key={p.id} p={p} busy={!!busy} onSave={url=>act("setFlowProject",{url})}/><div className="info-note"><CircleAlert size={16}/><p>O login acontece no Google. Salvar o link do projeto cria um atalho; a sessão da sua conta Flow não é compartilhada com o Contínuo.</p></div></section><section className="surface"><div className="integration-icon"><Sparkles size={26}/></div><div className="integration-heading"><h2>API oficial do Omni Flash</h2><span className={`badge ${configured||key?"approved":"draft"}`}>{configured?"Chave no servidor":key?"Chave nesta sessão":"A configurar"}</span></div><p>Gera e consulta cada clipe diretamente pelo servidor. Esta chave também habilita análise de fichas e roteiros, auditoria e propostas de ambientes.</p><Field label="Chave da Gemini API" hint="Mantida apenas na memória desta aba. Ao recarregar, informe novamente. Não enviamos a chave para o Flow."><input type="password" autoComplete="off" placeholder={configured?"Chave já configurada no servidor":"Cole sua chave da API"} value={key} onChange={e=>setKey(e.target.value.trim())}/></Field><Button kind="primary" disabled={!!busy||(!key&&!configured)} onClick={()=>run("Verificando a conexão",async()=>{const d=await raw("testConnection");setNotice(d.message);})}><Link2 size={16}/>Verificar conexão</Button>{key&&<Button kind="ghost" onClick={()=>{setKey("");setNotice("Chave removida desta sessão.");}}>Remover chave da sessão</Button>}<details className="api-setup-guide" open><summary><BookOpen size={16}/>Passo a passo da chave para análise automática</summary><ol className="numbered"><li>Abra <a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">Google AI Studio · API keys<ExternalLink size={11}/></a> e entre com sua conta Google.</li><li>Escolha criar uma chave de API e selecione ou crie o projeto Google.</li><li>Copie a chave e cole no campo acima. Clique em Verificar conexão.</li><li>Na Biblioteca oficial, abra o personagem e envie a imagem. Deixe Preencher automaticamente ativado.</li><li>Confira aparência, roupas, acessórios, proporções e paleta. Salve a ficha e aprove a referência.</li></ol><p className="help-text">Se o Google solicitar faturamento ou acesso a um modelo, configure o projeto no AI Studio. A geração Omni Flash usa a modalidade paga da API.</p><a className="guide-source" href="https://ai.google.dev/gemini-api/docs/api-key?hl=pt-br" target="_blank" rel="noreferrer">Instruções oficiais para a chave<ExternalLink size={12}/></a></details><div className="info-note"><CircleAlert size={16}/><p>A assinatura e os créditos do Google Flow não conectam nem pagam automaticamente esta API. Use um projeto Google com acesso e cobrança próprios.</p></div></section></div><section className="surface model-info"><h2>Regras do conector</h2><div className="model-grid"><div><strong>Omni Flash · 720p</strong><p>Todas as cenas têm 10 segundos em 720p. Escolha 16:9 (1280×720) ou 9:16 (720×1280). O modelo de vídeo é fixo: Omni Flash.</p></div><div><strong>Geração sequencial</strong><p>Uma cena por vez. Após a geração, extração dos frames e revisão liberam a próxima cena.</p></div><div><strong>Auditoria complementar</strong><p>Analisa clipes de até 12 MB com as imagens oficiais. Achados de IA ajudam a revisão; não garantem identidade perfeita.</p></div></div><p className="help-text">Disponibilidade, filtros e compatibilidade são definidos pelo Google. Erros do provedor são exibidos e as tentativas ficam preservadas.</p><div className="reference-links"><a href="https://ai.google.dev/gemini-api/docs/omni" target="_blank" rel="noreferrer">Documentação Omni Flash<ArrowUpRight size={13}/></a><a href="https://support.google.com/flow/answer/16353334?hl=pt-BR" target="_blank" rel="noreferrer">Ajuda do Flow<ArrowUpRight size={13}/></a></div></section></>}
        {view==="history"&&<><PageTitle eyebrow="MEMÓRIA DE PRODUÇÃO" title="Cada decisão fica registrada." text="Acompanhe revisões, versões de fichas e o andamento dos episódios."/><section className="surface reading-history"><div className="surface-title"><FileText size={20}/><h2>Consumo das fichas</h2></div><p className="help-text">Últimas 8 tentativas de análise. Salvar ou recuperar uma ficha não gera uma nova leitura. Leituras anteriores a esta atualização não têm consumo registrado.</p>{[...(state.referenceReadings||[])].reverse().map(r=><article className="saved-reading" key={r.id}><strong>{r.name||"Referência sem nome"} · {r.status==="complete"?"Concluída":r.status==="running"?"Aguardando resultado":"Não concluída"}</strong><p>{new Date(r.at).toLocaleString("pt-BR")} · {r.model}</p>{r.error&&<p>{r.error}</p>}{r.status!=="running"&&<UsageSummary usage={r.usage} estimate={r.estimate}/>}</article>)}<Button disabled={!!busy} onClick={()=>run("Atualizando consumo",load)}><RefreshCw size={14}/>Atualizar leituras</Button></section><section className="surface event-list">{[...state.events].reverse().map((e,i)=><div key={i}><div className="event-icon"><History size={16}/></div><div><strong>{e.text}</strong><time>{new Date(e.at).toLocaleString("pt-BR")}</time></div></div>)}</section></>}
        <footer className="main-footer"><span>CONTÍNUO <span>BY GOODEA</span></span><span>Uma boa história merece continuidade.</span><LockKeyhole size={12}/></footer>
      </main>
    </div>
    {notice&&<div className="toast" role="status"><Check size={17}/>{notice}</div>}
    {busy&&<div className="busy-toast" role="status"><Loader2 className="spin" size={16}/>{busy}…</div>}
    {newName!==null&&<div className="modal-backdrop" onClick={()=>!busy&&setNewName(null)}><section className="modal small" role="dialog" aria-modal="true" aria-label="Novo projeto" onClick={e=>e.stopPropagation()}><div className="modal-heading"><h2>Uma nova história.</h2><button className="icon-button" onClick={()=>setNewName(null)} aria-label="Fechar"><X size={20}/></button></div><p className="muted">A biblioteca oficial pode ser reutilizada em todos os episódios.</p><Field label="Nome do projeto"><input autoFocus placeholder="Título do episódio" value={newName} onChange={e=>setNewName(e.target.value)}/></Field><Button kind="primary" disabled={!newName.trim()||!!busy} onClick={()=>run("Criando projeto",async()=>{await raw("newProject",{name:newName});setNewName(null);setSelected("");setView("script");})}><Plus size={16}/>Criar projeto</Button></section></div>}
    {editor&&<ElementEditor key={editor.id||"new"} element={editor} busy={!!busy} onClose={()=>setEditor(null)} onSave={data=>run("Salvando ficha oficial",async()=>{await raw("saveElement",{...data,id:data.id||undefined});setEditor(null);setNotice("Ficha salva. Cenas que dependem desta versão precisam de revisão.");})} actionError={error} apiReady={!!key||configured} apiKeyValue={key} onApiKey={setKey} onAnalyze={analyzeReference} readings={state.referenceReadings||[]} onRefresh={()=>run("Atualizando leituras salvas",load)} onGenerate={id=>run("Gerando proposta de ambiente",async()=>{const d=await raw("generateEnvironment",{elementId:id});setEditor(d.state.elements.find((e:Element)=>e.id===id));setNotice("Proposta criada. Revise e aprove a ficha antes de usar.");})} onFiles={async(files:File[])=>{let result:FileRef[]=[];await run("Enviando referências",async()=>{for(const file of files)result.push(await upload(file));});return result;}}/>}
  </div>;
}

function PageTitle({eyebrow,title,text}:{eyebrow:string;title:string;text:string}){return <div className="page-title"><div className="eyebrow"><span/>{eyebrow}</div><h1>{title}</h1><p>{text}</p></div>;}
function SceneEditor({scene,elements,busy,onSave,onRemove,onMove,onPrompt}:{scene:Scene;elements:Element[];busy:boolean;onSave:(s:Scene)=>void;onRemove:()=>void;onMove:(s:string)=>void;onPrompt:()=>void}){const [s,set]=useState({...structuredClone(scene),duration:10});const patch=(x:Partial<Scene>)=>set({...s,...x});function line(i:number,x:Partial<Line>){patch({lines:s.lines.map((l,n)=>n===i?{...l,...x}:l)});}return <form className="panel-body direction-form" onSubmit={e=>{e.preventDefault();onSave(s);}}><Field label="Título da cena"><input value={s.title} onChange={e=>patch({title:e.target.value})} required/></Field><div className="form-grid"><Field label="Duração fixa"><input value="10 segundos · Omni Flash 720p" readOnly/></Field><Field label="Ligação entre cenas"><select value={s.transition} onChange={e=>patch({transition:e.target.value as any})}><option value="continue">Continuação direta</option><option value="cut">Corte planejado</option></select></Field></div><Field label="Ambiente"><select value={s.environment} onChange={e=>patch({environment:e.target.value})}><option value="">Selecionar ambiente</option>{s.environment.startsWith("pending:")&&<option value={s.environment}>{s.environment.replace("pending:","")} · não cadastrado</option>}{elements.filter(e=>e.kind==="environment").map(e=><option key={e.id} value={e.id}>{e.name}{e.approved?" · oficial":" · em preparação"}</option>)}</select></Field><div className="field"><span>Elenco desta cena · um de cada</span><div className="cast-selector">{elements.filter(e=>e.kind==="character").map(e=><button key={e.id} type="button" className={s.characters.includes(e.id)?"selected":""} onClick={()=>patch({characters:s.characters.includes(e.id)?s.characters.filter(id=>id!==e.id):[...s.characters,e.id]})}>{s.characters.includes(e.id)?<Check size={13}/>:<Plus size={13}/>} {e.name}</button>)}</div>{s.characters.filter(id=>id.startsWith("pending:")).map(id=><button type="button" className="pending-cast" key={id} onClick={()=>patch({characters:s.characters.filter(v=>v!==id)})}>{id.replace("pending:","")} · não cadastrado <X size={12}/></button>)}</div><Field label="Ação e posição dos personagens"><textarea rows={4} value={s.action} onChange={e=>patch({action:e.target.value})} required/></Field><Field label="Câmera e enquadramento"><input value={s.camera} onChange={e=>patch({camera:e.target.value})}/></Field><div className="field"><span>Falas e narração · ordem de execução</span>{s.lines.map((l,i)=><div className="line-editor" key={i}><div><select value={l.type} onChange={e=>line(i,{type:e.target.value as any,speaker:e.target.value==="narration"?"Narrador":s.characters[0]?elementName(s.characters[0],elements):""})}><option value="dialogue">Fala</option><option value="narration">Narração</option></select>{l.type==="dialogue"&&<input placeholder="Quem fala?" value={l.speaker} onChange={e=>line(i,{speaker:e.target.value})}/>}<button type="button" className="icon-button" aria-label="Remover fala" onClick={()=>patch({lines:s.lines.filter((_,n)=>n!==i)})}><X size={14}/></button></div><textarea rows={2} value={l.text} placeholder="Texto exato em português" onChange={e=>line(i,{text:e.target.value})}/></div>)}<Button kind="ghost" onClick={()=>patch({lines:[...s.lines,{type:"dialogue",speaker:s.characters[0]?elementName(s.characters[0],elements):"",text:""}]})}><Plus size={14}/>Adicionar fala ou narração</Button></div><Field label="Som ambiente"><textarea rows={2} value={s.sound} onChange={e=>patch({sound:e.target.value})}/></Field><Field label="Notas de direção"><textarea rows={2} value={s.notes} onChange={e=>patch({notes:e.target.value})}/></Field><Button type="submit" kind="primary" disabled={busy}><Check size={16}/>Salvar direção</Button><div className="inline-actions"><Button onClick={onPrompt} disabled={busy}><Copy size={14}/>Copiar prompt salvo</Button><Button onClick={()=>onMove("up")} disabled={busy}><ArrowUp size={14}/>Subir</Button><Button onClick={()=>onMove("down")} disabled={busy}><ArrowDown size={14}/>Descer</Button><Button kind="danger" onClick={onRemove} disabled={busy}><Trash2 size={14}/>Remover</Button></div><small className="help-text">Alterar direção ou ordem invalida esta cena e as seguintes. O prompt usa a última direção salva.</small></form>;}
function Review({scene,busy,pending,onSave,onReject,onAudit,onFrames}:{scene:Scene;busy:boolean;pending:string[];onSave:(data:any)=>void;onReject:(s:string)=>void;onAudit:()=>void;onFrames:()=>void}){const [checked,setChecked]=useState(scene.checked),[notes,setNotes]=useState(scene.notes);return <div className="panel-body review-panel">{scene.video?<video src={mediaUrl(scene.video)} controls playsInline preload="metadata"/>:<Empty title="A cena ainda não foi produzida" text="Importe o clipe na aba Produção para iniciar a revisão."/>}<div className="review-heading"><ShieldCheck size={20}/><div><h3>A identidade passa por você.</h3><p>Assista ao vídeo completo e confira cada item.</p></div></div>{checks.map((label,i)=><label className="check-row" key={label}><input type="checkbox" checked={checked[i]||false} onChange={e=>setChecked(checked.map((b,n)=>n===i?e.target.checked:b))} disabled={!scene.video||busy}/><span>{label}</span></label>)}<Field label="Observações da revisão"><textarea rows={3} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Registre divergências, correções ou decisões."/></Field>{scene.video&&!scene.lastFrame&&<Button onClick={onFrames} disabled={busy}><Scissors size={16}/>Extrair frames antes de aprovar</Button>}{scene.audit&&<div className={`audit-result ${scene.audit.verdict}`}><strong>Auditoria IA · {scene.audit.verdict==="pass"?"sem divergências observadas":scene.audit.verdict==="reject"?"divergências encontradas":"inconclusiva"}</strong><ul>{scene.audit.findings.map((x,i)=><li key={i}>{x}</li>)}</ul></div>}<Button onClick={onAudit} disabled={busy||!scene.video}><Sparkles size={16}/>Auditar clipe com IA<span className="tiny-tag">requer API</span></Button><p className="help-text">A análise pode deixar passar erros e não substitui a revisão humana. Rejeições da auditoria exigem uma nova tomada.</p>{pending.length>0&&<div className="locked-note"><LockKeyhole size={15}/>Resolva as pendências da produção antes de aprovar.</div>}{scene.status==="stale"&&<div className="locked-note"><RefreshCw size={16}/>O contexto mudou. Importe uma nova tomada para continuar.</div>}<div className="flow-actions"><Button kind="primary" disabled={busy||!scene.video||!scene.lastFrame||pending.length>0||!checked.every(Boolean)||scene.status==="stale"} onClick={()=>onSave({checked,notes,approve:true})}><ShieldCheck size={16}/>Aprovar cena</Button><Button disabled={busy||!scene.video} onClick={()=>onSave({checked,notes,approve:false})}>Salvar revisão</Button><Button kind="danger" disabled={busy||!scene.video} onClick={()=>onReject(notes||"Tomada rejeitada. Gere uma nova versão.")}><RefreshCw size={14}/>Pedir nova tomada</Button></div></div>;}
function ScriptEditor({p,busy,onParse,onSave}:{p:Project;busy:boolean;onParse:(s:string,ai:boolean)=>void;onSave:(d:any)=>void}){const [data,set]=useState({...p});const patch=(x:Partial<Project>)=>set({...data,...x});return <div className="script-layout"><section className="surface script-surface"><div className="surface-title"><FileText size={20}/><h2>Seu roteiro</h2><span className="tiny-tag">PT-BR</span></div><textarea className="script-text" spellCheck value={data.script} onChange={e=>patch({script:e.target.value})} placeholder={"CENA 01 | Título | 10s\nAMBIENTE: Casa da Luz\nPERSONAGENS: Emanuel, Bento\nAÇÃO: Descreva o que acontece.\nEMANUEL: Texto exato da fala.\nNARRAÇÃO: Texto fora de cena.\nCÂMERA: Plano médio."}/><div className="script-actions"><Button kind="primary" onClick={()=>onParse(data.script,false)} disabled={busy||!data.script.trim()||p.scenes.some(s=>s.video||s.operation)}><Scissors size={16}/>Identificar cenas</Button><Button onClick={()=>onParse(data.script,true)} disabled={busy||!data.script.trim()||p.scenes.some(s=>s.video||s.operation)}><Sparkles size={16}/>Interpretar com IA</Button></div><p className="help-text">Identificação padrão usa os rótulos CENA, AMBIENTE, PERSONAGENS, AÇÃO e NARRAÇÃO. A interpretação por IA exige chave da API. Sempre revise os resultados.</p>{p.scenes.some(s=>s.video||s.operation)&&<div className="locked-note"><LockKeyhole size={15}/>Este projeto já tem vídeos. Edite as cenas no Estúdio ou inicie um novo projeto para redividir o roteiro.</div>}</section><form className="surface project-settings" onSubmit={e=>{e.preventDefault();onSave(data);}}><div className="surface-title"><Palette size={20}/><h2>Identidade do projeto</h2></div><Field label="Nome do projeto"><input required value={data.name} onChange={e=>patch({name:e.target.value})}/></Field><Field label="Formato do filme"><select value={data.aspect} onChange={e=>patch({aspect:e.target.value as any})}><option value="16:9">16:9 · Horizontal</option><option value="9:16">9:16 · Vertical</option></select></Field><div className="fixed-video-profile"><Video size={16}/><span>Omni Flash · 10 segundos · 720p</span><LockKeyhole size={12}/></div><Field label="Estilo visual"><textarea rows={3} value={data.style} onChange={e=>patch({style:e.target.value})}/></Field><Field label="Paleta e materiais"><textarea rows={3} value={data.palette} onChange={e=>patch({palette:e.target.value})}/></Field><Field label="Regras obrigatórias"><textarea rows={7} value={data.rules} onChange={e=>patch({rules:e.target.value})}/></Field><Button type="submit" kind="primary" disabled={busy}><Check size={16}/>Salvar projeto e roteiro</Button><div className="info-note"><ShieldCheck size={18}/><p>As fichas da biblioteca são a referência principal. A identidade do projeto complementa as regras e não substitui os arquivos oficiais.</p></div></form></div>;}
function AudioUpload({title,text,file,busy,onFile,onRemove}:{title:string;text:string;file?:FileRef;busy:boolean;onFile:(f:File)=>void;onRemove:()=>void}){return <div className="audio-upload"><div className="audio-upload-heading"><div className="audio-icon"><Music2 size={18}/></div><div><strong>{title}</strong><p>{text}</p></div></div>{file?<><audio controls preload="metadata" src={mediaUrl(file)}/><div className="file-row"><span>{file.name}</span><button className="icon-button" disabled={busy} onClick={onRemove} aria-label="Remover áudio"><Trash2 size={15}/></button></div></>:<label className={`upload-zone ${busy?"disabled":""}`}><Upload size={19}/><span>Importar áudio oficial</span><small>MP3, WAV, OGG ou M4A · até 80 MB</small><input disabled={busy} type="file" accept="audio/*" onChange={e=>{const f=e.target.files?.[0];if(f)onFile(f);e.target.value="";}}/></label>}</div>;}
function MixSettings({p,busy,onSave}:{p:Project;busy:boolean;onSave:(d:any)=>void}){const [volume,setVolume]=useState(p.musicVolume),[mute,setMute]=useState(p.muteOriginal);return <div className="mix-settings"><Field label={`Volume da música · ${Math.round(volume*100)}%`}><input type="range" min={0} max={1} step={0.01} value={volume} onChange={e=>setVolume(Number(e.target.value))}/></Field><label className="check-row"><input type="checkbox" checked={mute} onChange={e=>setMute(e.target.checked)}/><span>Silenciar o áudio original dos clipes</span></label><p className="help-text">Use ao substituir todas as vozes pela faixa mestre. Áudio por cena sempre substitui o original daquela cena.</p><Button disabled={busy} onClick={()=>onSave({...p,musicVolume:volume,muteOriginal:mute})}>Salvar mixagem</Button></div>;}
function ElementEditor({element,busy,onClose,onSave,onFiles,onGenerate,apiReady,apiKeyValue,onApiKey,onAnalyze,actionError,readings,onRefresh}:{element:Element;busy:boolean;onClose:()=>void;onSave:(e:Element)=>void;onFiles:(f:File[])=>Promise<FileRef[]>;onGenerate:(id:string)=>void;apiReady:boolean;apiKeyValue:string;onApiKey:(key:string)=>void;onAnalyze:(e:Element,force?:boolean,countOnly?:boolean)=>Promise<AnalysisResponse>;actionError:string;readings:ReferenceReading[];onRefresh:()=>void}){
  const [data,set]=useState(structuredClone(element)),[automatic,setAutomatic]=useState(true),[analysisMessage,setAnalysisMessage]=useState(""),[analysisError,setAnalysisError]=useState(""),[inputCount,setInputCount]=useState<number|undefined>(undefined);
  useEffect(()=>set(structuredClone(element)),[element]);
  useEffect(()=>setInputCount(undefined),[data.name,data.files]);
  const patch=(x:Partial<Element>)=>set(d=>({...d,...x}));
  async function analyze(draft:Element,force=false){
    setAnalysisError("");setAnalysisMessage("");
    if(!apiReady){setAnalysisMessage("A imagem está pronta. Informe sua chave da Gemini API abaixo e clique em Analisar imagem e preencher ficha.");return;}
    const result=await onAnalyze(draft,force);
    if(result.error){setAnalysisError(result.error);return;}
    if(result.proposal){set({...draft,...result.proposal,approved:false});setAnalysisMessage(result.reused?"Leitura recuperada, sem nova chamada ao Google. Os tokens abaixo são da leitura original.":"Ficha preenchida automaticamente. Confira os detalhes e o consumo antes de salvar.");}
  }
  const image=data.files.find(f=>f.mime.startsWith("image/"));
  const related=[...readings].reverse().filter(r=>r.kind===data.kind&&((r.name&&r.name===data.name)||r.fileIds.some(id=>data.files.some(f=>f.id===id))));
  const keys=(Object.keys(visualLabels) as (keyof typeof visualLabels)[]).filter(k=>data.kind==="character"?k!=="environment":["style","lighting","environment"].includes(k));
  return <div className="modal-backdrop" onClick={()=>!busy&&onClose()}><form className="modal element-modal" role="dialog" aria-modal="true" aria-label="Ficha oficial" onClick={e=>e.stopPropagation()} onSubmit={e=>{e.preventDefault();onSave(data);}}>
    <div className="modal-heading"><div><div className="eyebrow">BIBLIOTECA OFICIAL · {data.kind==="character"?"PERSONAGEM":"AMBIENTE"}</div><h2>{data.name||"Uma nova referência."}</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Fechar ficha" disabled={busy}><X size={20}/></button></div>
    {actionError&&<div className="alert error" role="alert"><CircleAlert size={16}/>{actionError}</div>}<fieldset className="element-form-grid" disabled={busy}><div>
      <div className="reference-preview">{image?<img src={mediaUrl(image)} alt="Referência da ficha"/>:<Empty icon={<ImageIcon size={30}/>} title="Envie a imagem do personagem" text="A leitura identifica os detalhes visíveis e preenche a ficha para sua revisão."/>}</div>
      <label className="check-row auto-fill-option"><input type="checkbox" checked={automatic} onChange={e=>setAutomatic(e.target.checked)} disabled={busy}/><span>Preencher automaticamente ao enviar imagem</span></label>
      <label className={`upload-zone compact ${busy?"disabled":""}`}><Upload size={18}/><span>Adicionar imagem ou ficha</span><small>PNG/JPG/WebP · PDF/TXT · amostra de áudio</small><input type="file" disabled={busy} multiple accept="image/png,image/jpeg,image/webp,application/pdf,text/plain,audio/*" onChange={async e=>{const input=e.target,files=Array.from(input.files||[]);input.value="";if(!files.length)return;const refs=await onFiles(files);if(!refs.length)return;const draft={...data,files:[...data.files,...refs],approved:false,analysis:undefined};set(draft);if(automatic&&draft.files.some(f=>f.mime.startsWith("image/")))await analyze(draft);}}/></label>
      <div className="reference-files">{data.files.map((f,i)=><div className="file-row" key={f.id}><a href={mediaUrl(f)} target="_blank" rel="noreferrer">{f.mime.startsWith("image/")?<ImageIcon size={14}/>:f.mime.startsWith("audio/")?<Mic size={14}/>:<FileText size={14}/>}<span>{f.name}</span></a><button type="button" className="icon-button" aria-label="Remover referência" onClick={()=>patch({files:data.files.filter((_,n)=>n!==i),approved:false,analysis:undefined})} disabled={busy}><X size={14}/></button></div>)}</div>
      {(!apiReady||apiKeyValue)&&<div className="image-key-setup"><strong><Sparkles size={14}/>Ativar leitura da imagem</strong><p>Use uma chave da Gemini API para a análise. O login no Flow é feito separadamente.</p><Field label="Chave da Gemini API"><input type="password" autoComplete="off" value={apiKeyValue} placeholder="Cole sua chave da API" onChange={e=>onApiKey(e.target.value.trim())}/></Field><a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">Criar chave no Google AI Studio<ExternalLink size={12}/></a></div>}
      <Button kind="primary" onClick={()=>analyze(data)} disabled={busy||!image}><Sparkles size={16}/>Analisar imagem e preencher ficha</Button>
      <div className="token-actions"><Button onClick={async()=>{setAnalysisError("");const r=await onAnalyze(data,false,true);if(r.error)setAnalysisError(r.error);else setInputCount(r.inputTokens);}} disabled={busy||!image||!apiReady}><FileText size={14}/>Contar tokens antes de analisar</Button>{(data.analysis||related.length>0)&&<Button onClick={()=>analyze(data,true)} disabled={busy||!image||!apiReady}><RefreshCw size={14}/>Nova análise (consome tokens)</Button>}</div>
      {inputCount!==undefined&&<p className="token-count" role="status"><strong>{inputCount.toLocaleString("pt-BR")} tokens de entrada</strong> para o texto e os arquivos atuais. Resposta e raciocínio serão medidos após a análise.</p>}
      {analysisMessage&&<div className="analysis-message" role="status"><Check size={15}/><p>{analysisMessage}</p></div>}
      {analysisError&&<div className="alert error" role="alert"><CircleAlert size={16}/>{analysisError}</div>}
      <p className="help-text">Nome, voz e detalhes ocultos precisam de evidência na ficha ou em áudio. A análise deixa a aprovação com você.</p>
      {data.analysis&&<div className="analysis-evidence"><strong><ShieldCheck size={14}/>Leitura das referências</strong><span>{new Date(data.analysis.at).toLocaleString("pt-BR")} · {data.analysis.fileIds.length} arquivos · {data.analysis.model||"modelo não registrado"}</span><UsageSummary usage={data.analysis.usage} estimate={data.analysis.estimate}/>{data.analysis.uncertainties.length>0&&<ul>{data.analysis.uncertainties.map((u,i)=><li key={i}>{u}</li>)}</ul>}</div>}
      <details className="saved-readings" open={related.some(r=>r.status!=="complete")}><summary>Leituras salvas · {related.length}</summary><p>Atualize para verificar uma leitura que terminou sem aparecer na tela. Recuperar uma ficha salva não envia outra análise.</p><Button onClick={onRefresh} disabled={busy}><RefreshCw size={14}/>Atualizar leituras salvas</Button>{related.slice(0,3).map(r=><div className="saved-reading" key={r.id}><strong>{new Date(r.at).toLocaleString("pt-BR")} · {r.status==="complete"?"Concluída":r.status==="running"?"Aguardando resultado":"Não concluída"}</strong>{r.error&&<p>{r.error}</p>}{r.status!=="running"&&<UsageSummary usage={r.usage} estimate={r.estimate}/>} {r.result&&<Button disabled={busy} onClick={()=>{set({...data,...referenceProposal(data,r),files:r.files||data.files,approved:false});setAnalysisError("");setAnalysisMessage("Ficha recuperada sem nova chamada ao Google. Confira os campos e salve.");}}><History size={14}/>Recuperar ficha sem reanalisar</Button>}</div>)}</details>
      {data.kind==="environment"&&data.id&&!data.approved&&<><Button onClick={()=>onGenerate(data.id)} disabled={busy}><Sparkles size={16}/>Gerar proposta de ambiente</Button><p className="help-text">Salve as regras antes de gerar a proposta. Ela precisa de aprovação.</p></>}
    </div><div>
      <Field label="Nome oficial" hint="Preenchido quando o nome aparece na referência. Se não aparecer, informe o nome oficial."><input required value={data.name} onChange={e=>patch({name:e.target.value})}/></Field>
      <Field label={data.kind==="character"?"Ficha e regras de identidade":"Ficha de ambiente e arquitetura"} hint="Preenchida pela análise e editável. As regras anteriores são preservadas."><textarea rows={6} value={data.rules} onChange={e=>patch({rules:e.target.value,approved:false})} required/></Field>
      <Field label="Paleta, materiais e iluminação"><textarea rows={3} value={data.palette} onChange={e=>patch({palette:e.target.value,approved:false})}/></Field>
      {data.visualDetails&&<details className="visual-details" open><summary><ImageIcon size={15}/>Detalhes identificados na imagem</summary>{keys.map(k=><Field key={k} label={visualLabels[k]}><textarea rows={2} value={data.visualDetails?.[k]||""} onChange={e=>patch({visualDetails:{...data.visualDetails,[k]:e.target.value},approved:false})}/></Field>)}</details>}
      {data.kind==="character"&&<><Field label="Descrição da voz oficial" hint="Uma imagem não revela o timbre nem o sotaque. Envie áudio ou ficha com uma descrição explícita."><textarea rows={3} value={data.voice} onChange={e=>patch({voice:e.target.value,approved:false})}/></Field><Field label="Identificador da voz no seu provedor" hint="Use o nome do preset aprovado na produção de áudio."><input placeholder="Nome do preset oficial" value={data.voiceId} onChange={e=>patch({voiceId:e.target.value,approved:false})}/></Field></>}
      <label className="approve-element"><input type="checkbox" checked={data.approved} onChange={e=>patch({approved:e.target.checked})}/><ShieldCheck size={20}/><span><strong>Aprovar como referência oficial</strong><small>Conferi imagens, ficha e regras deste cadastro.</small></span></label>
    </div></fieldset>
    <div className="modal-footer"><p>Os campos estão em rascunho até você salvar. Alterar uma ficha invalida as cenas dependentes.</p><Button type="submit" kind="primary" disabled={busy}><Check size={16}/>Salvar ficha</Button></div>
  </form></div>;
}

function UsageSummary({usage,estimate}:{usage?:TokenUsage;estimate?:CostEstimate}){
  if(!usage)return <p className="usage-unknown">Consumo não registrado. Não é possível calcular os tokens dessa leitura antiga ou sem confirmação.</p>;
  const n=(v:number|undefined)=>v===undefined?"Não informado":v.toLocaleString("pt-BR");
  return <div className="token-usage"><strong>Tokens informados pelo Google</strong><dl><div><dt>Entrada: texto e arquivos</dt><dd>{n(usage.input)}</dd></div><div><dt>Resposta</dt><dd>{n(usage.output)}</dd></div><div><dt>Raciocínio</dt><dd>{n(usage.thinking)}</dd></div><div><dt>Cache, incluído na entrada</dt><dd>{n(usage.cached)}</dd></div><div className="usage-total"><dt>Total informado</dt><dd>{n(usage.total)}</dd></div></dl>{estimate?<><p className="usage-cost">Estimativa: <strong>{estimate.usd.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:5,maximumFractionDigits:6})}</strong></p><p>Tarifa paga padrão em {new Date(estimate.asOf+"T12:00:00Z").toLocaleDateString("pt-BR")}: US$ {estimate.inputRate}/milhão na entrada, US$ {estimate.outputRate}/milhão na saída, incluindo raciocínio. Pode variar conforme gratuidade, plano e impostos. <a href={estimate.source} target="_blank" rel="noreferrer">Preços do Google</a></p></>:<p>O Google não informou todos os dados necessários para estimar o custo.</p>}</div>;
}

function DirectGeneration({p,scene,elements,ready,busy,onSettings,onGenerate,onPoll}:{p:Project;scene:Scene;elements:Element[];ready:boolean;busy:boolean;onSettings:()=>void;onGenerate:()=>void;onPoll:()=>void}){
  return <div className="api-generation direct-generation"><div><Sparkles size={16}/><span>Gerar pela Gemini API</span></div>
    <p className="generation-mode">Omni Flash pela Gemini API. A cobrança usa o projeto da chave Gemini, separadamente da assinatura Flow.</p>
    <div className="inline-actions"><Button kind="primary" disabled={busy||!ready||!!scene.operation||!!preflight(p,scene,elements).length} onClick={onGenerate}><Play size={15}/>Gerar com Omni Flash</Button><Button onClick={onSettings} disabled={busy}><Link2 size={14}/>Configurar Gemini API</Button>{scene.operation&&<Button onClick={onPoll} disabled={busy}><RefreshCw size={14}/>Consultar andamento</Button>}</div>
    {!ready&&<p className="help-text">Configure o acesso à Gemini API em Integrações para habilitar a geração.</p>}
  </div>;
}

function FlowSetupGuide({p,busy,onSave}:{p:Project;busy:boolean;onSave:(url:string)=>void}){
  const [url,setUrl]=useState(p.flowProjectUrl||"");
  useEffect(()=>setUrl(p.flowProjectUrl||""),[p.flowProjectUrl]);
  return <div className="flow-setup-guide"><a className="btn primary" href={p.flowProjectUrl||"https://flow.google.com/"} target="_blank" rel="noreferrer"><ExternalLink size={15}/>{p.flowProjectUrl?"Abrir meu projeto no Google Flow":"Entrar no Google Flow"}</a><ol className="numbered">
    <li>Abra o Flow pelo botão acima. Faça login no Google com a conta que tem acesso ao serviço. Confira a conta no menu de perfil.</li>
    <li>Crie um projeto ou abra o projeto do seu episódio. Copie o endereço da página e salve no campo abaixo para voltar ao mesmo projeto.</li>
    <li>No Contínuo, cadastre e aprove as referências em Biblioteca oficial. Em Estúdio, escolha a primeira cena e baixe Pacote para o Flow.</li>
    <li>Extraia o ZIP. No Flow, selecione Vídeo e o modelo Omni Flash. Escolha 720p, duração de 10s e a mesma proporção definida no Contínuo (16:9 ou 9:16).</li>
    <li>Para a abertura, use Elementos e envie as imagens oficiais. Cole o texto de prompt.txt e gere a cena.</li>
    <li>Baixe o vídeo gerado. No Contínuo, escolha Importar vídeo, assista ao clipe e aprove a revisão.</li>
    <li>Na próxima cena, baixe o novo pacote. No Flow, use Vídeo → Frames e arraste CONTINUIDADE-frame-inicial.png para Adicionar frame inicial. Cole o prompt da nova cena e gere.</li>
    <li>Repita a produção e a revisão. Após todas as cenas aprovadas, abra Áudio e montagem para unir o episódio.</li>
  </ol><details className="api-setup-guide"><summary><Mic size={15}/>Reutilizar a voz no próprio Flow</summary><p className="help-text">Com Omni Flash, abra Vídeo → Elementos → Adicionar → Vozes. Escolha ou crie a voz do personagem, salve com o mesmo nome e referencie essa voz nos próximos clipes. A voz é configurada dentro do Flow; uma imagem do personagem não define seu timbre.</p><a className="guide-source" href="https://support.google.com/flow/answer/16353334?hl=pt-BR" target="_blank" rel="noreferrer">Instruções oficiais de referências de voz<ExternalLink size={12}/></a></details><Field label="Link do projeto do episódio no Flow" hint="Este é um atalho para seu projeto; não solicita senha, código de login ou cookies da conta."><input type="url" placeholder="https://labs.google/fx/tools/flow/..." value={url} onChange={e=>setUrl(e.target.value)} disabled={busy}/></Field><Button onClick={()=>onSave(url)} disabled={busy}><Link2 size={14}/>{url.trim()?"Salvar atalho do projeto":"Remover atalho"}</Button><a className="guide-source" href="https://support.google.com/flow/answer/16353334?hl=pt-BR" target="_blank" rel="noreferrer">Ajuda oficial: referências e frames<ExternalLink size={12}/></a></div>;
}

function VideoProfileControls({p,busy,onAspect}:{p:Project;busy:boolean;onAspect:(aspect:"16:9"|"9:16")=>void}){return <div className="video-profile-controls"><div><Video size={19}/><div><strong>Omni Flash <span>720p</span></strong><small>10 segundos por cena · modelo e resolução fixos</small></div></div><div className="format-options" role="group" aria-label="Formato do vídeo"><button type="button" className={p.aspect==="16:9"?"selected":""} disabled={busy} onClick={()=>onAspect("16:9")}><span className="aspect-icon landscape"/><span>16:9<small>Horizontal</small></span>{p.aspect==="16:9"&&<Check size={13}/>}</button><button type="button" className={p.aspect==="9:16"?"selected":""} disabled={busy} onClick={()=>onAspect("9:16")}><span className="aspect-icon vertical"/><span>9:16<small>Vertical</small></span>{p.aspect==="9:16"&&<Check size={13}/>}</button></div></div>;}
